class RCCRunner:
    def __init__(self, binary, home, scrub_root=None):
        self.binary = str(Path(binary).resolve())
        if not Path(self.binary).is_file() or not os.access(self.binary, os.X_OK):
            raise ValueError("--binary must name an executable RCC candidate")
        self.home = Path(home)
        self.scrub_root = scrub_root or self.home.parent
        self.run_env = {}

    def run(self, args, phase):
        command = [self.binary, *args]
        started = time.perf_counter_ns()
        with tempfile.TemporaryFile(mode="w+t", encoding="utf-8") as stdout, tempfile.TemporaryFile(
                mode="w+t", encoding="utf-8") as stderr:
            process = subprocess.Popen(command, env={**os.environ, **self.run_env, "ROBOCORP_HOME": str(self.home)},
                                       stdout=stdout, stderr=stderr, text=True)
            if hasattr(os, "wait4"):
                _, status, usage = os.wait4(process.pid, 0)
                process.returncode = os.waitstatus_to_exitcode(status)
            else:
                process.wait()
                usage = None
            stdout.seek(0)
            stderr.seek(0)
            result = {"returncode": process.returncode, "stdout": stdout.read().strip(),
                      "stderr": stderr.read().strip()}

func (it Manifest) IdentityBytes() ([]byte, error) {
	return canonicalEncode(manifestIdentity{
		MediaType: it.MediaType, SchemaVersion: it.SchemaVersion,
		Specification: it.Specification, LegacyBlueprint: it.LegacyBlueprint,
		Platform: it.Platform, Builder: it.Builder, Catalogs: it.Catalogs,
		ObjectIndex: it.ObjectIndex, Requirements: it.Requirements,
	})
}

func (it Manifest) Validate() error {
	if it.MediaType != ManifestMediaType || it.SchemaVersion != SchemaVersionV1 {
		return fmt.Errorf("unsupported manifest media type or schema version")
	}
	if err := it.Platform.Validate(); err != nil {
		return err
	}
	if it.Specification.MediaType != SpecificationMediaType || it.LegacyBlueprint.MediaType != LegacyBlueprintMediaType || it.ObjectIndex.MediaType != ObjectIndexMediaType {
		return fmt.Errorf("unsupported manifest descriptor media type")
	}
	if it.Specification.Platform != it.Platform || it.Specification.Builder != it.Builder {
		return fmt.Errorf("specification metadata contradicts manifest platform or builder")
	}
	if it.Specification.Digest == it.LegacyBlueprint.Digest {
		return fmt.Errorf("semantic specification and legacy blueprint identities are conflated")
	}
	if !legacyKeyPattern.MatchString(it.LegacyBlueprint.LegacyBlueprintKey) {
		return fmt.Errorf("invalid legacy blueprint key")
	}
	if len(it.Catalogs) != 1 || it.Catalogs[0].MediaType != CatalogV12MediaType {
		return fmt.Errorf("manifest v1 requires exactly one v12 gzip catalog")
	}
	wantCatalogName := it.LegacyBlueprint.LegacyBlueprintKey + "v12." + it.Platform.RCCPlatform
	if it.Catalogs[0].LegacyName != wantCatalogName {
		return fmt.Errorf("catalog legacy name does not match legacy blueprint key")
	}
	if !strings.HasSuffix(it.Catalogs[0].LegacyName, "v12."+it.Platform.RCCPlatform) {
		return fmt.Errorf("catalog platform does not match manifest platform")
	}
	if it.Requirements.CatalogReader != "v12" || it.Requirements.Encoding != "gzip" || it.Requirements.LegacyLogicalDigestAlgorithm != "sha256" || len(it.Requirements.RequiredFeatures) != 0 {
		return fmt.Errorf("unsupported manifest requirements")
	}
	if err := it.Requirements.Compatibility.Validate(); err != nil {
		return fmt.Errorf("invalid compatibility requirements: %w", err)

func (it ObjectIndex) Validate() error {
	if it.MediaType != ObjectIndexMediaType || it.SchemaVersion != SchemaVersionV1 {
		return fmt.Errorf("unsupported object index media type or schema version")
	}
	if it.Encoding != "gzip" || it.LegacyLogicalDigestAlgorithm != "sha256" {
		return fmt.Errorf("unsupported object index encoding or logical digest")
	}
	if it.Count != len(it.Entries) {
		return fmt.Errorf("object index count mismatch")
	}
	var storedTotal, logicalTotal int64
	previous := ""
	for _, entry := range it.Entries {
		if !legacyObjectIDPattern.MatchString(entry.LegacyObjectID) {
			return fmt.Errorf("invalid legacy object ID %q", entry.LegacyObjectID)
		}
		if previous != "" && entry.LegacyObjectID <= previous {
			return fmt.Errorf("object entries are not strictly sorted and unique")
		}
		if entry.StoredDigest.hex == "" || entry.StoredSize < 0 || entry.LogicalSize < 0 {
			return fmt.Errorf("invalid object descriptor for %s", entry.LegacyObjectID)
		}
		if entry.Encoding != it.Encoding || entry.LegacyLogicalDigestAlgorithm != it.LegacyLogicalDigestAlgorithm {
			return fmt.Errorf("mixed object storage mode")
		}
		previous = entry.LegacyObjectID
		storedTotal += entry.StoredSize
		logicalTotal += entry.LogicalSize
	}
	if storedTotal != it.TotalStoredBytes || logicalTotal != it.TotalLogicalBytes {
		return fmt.Errorf("object index totals mismatch")
	}
